import json, pathlib, hashlib
P=pathlib.Path(__file__).parent
D=P/'data'
def save(name,rows):
 (D/name).write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in rows),encoding='utf-8')
facts=[
['Инцидент турнира «Орион» зарегистрирован 14 марта 2026 года.','Окно заморозки началось в 18:00.','Окно заморозки закончилось в 19:00.','Контрольная сборка опубликована в 18:25.'],
['В 18:10 Ладе предоставлено право чтения.','В 18:20 Ладе впервые предоставлено право публикации.','В 18:15 сборку опубликовала служба «Шлюз».','В 18:12 зарегистрирован успешный вход Лады.'],
['Во время заморозки публикация запрещена.','Исключение требует одновременно резервного ключа и письменного разрешения координатора.','Резервный ключ включён в 18:22.','Письменное разрешение координатора Веры получено в 18:24.'],
['Илья сообщил: «В 18:15 Лада находилась в серверной».','Илья сообщил: «В 18:15 индикатор был красным».','Илья сообщил: «Я работал с настройками задания службы».','Илья сообщил: «После запуска я ушёл в зал».'],
['Мира сообщила: «В 18:15 Лада не находилась в серверной».','Мира сообщила: «В 18:15 индикатор был зелёным».','Мира сообщила: «Часы в зале я не проверяла».','Мира сообщила: «Ключ от серверной лежал на столе».'],
['Вера сообщила: «Причину первого выпуска я не знаю».','Вера написала: «Разрешаю резервную публикацию в 18:24».','Вера сообщила: «Намерения Ильи мне неизвестны».','Вера сообщила: «Личность скачавшего архив не установлена».'],
['Журнал аудита не фиксирует включения резервного ключа до 18:22.','Контрольная сумма первого выпуска равна OR-15.','Контрольная сумма второго выпуска равна OR-25.','Первое задание было поставлено в очередь в 17:55.'],
['Репетиция турнира проходила 13 марта.','На репетиции использовался макет серверной.','На репетиции зелёный индикатор означал паузу.','Архив репетиции назывался OR-DEMO.'],
['В апрельской программе запланирован турнир «Вектор».','В программе «Вектор» предусмотрен красный плакат.','Для «Вектора» заказали двадцать стульев.','Программа «Вектор» не является регламентом «Ориона».']]
titles=['Карточка инцидента и частичная временная шкала','Журнал доступа','Регламент и резервное исключение','Показания Ильи','Показания Миры','Сообщение и переписка Веры','Технический аудит','Архив репетиции','План другого турнира']
# Развёрнутые материалы редактора досье; не добавляют скрытых причин или результатов.
docs=[];claims=[]
for i,fs in enumerate(facts):
 did=f'D{i+1:02}'; typ='statement' if i in (3,4,5) else 'rule' if i==2 else 'document'
 text='\n\n'.join([titles[i]+'. Все события и лица вымышлены.',('Частичная временная шкала:\n'+'\n'.join(fs[k] for k in (0,1,3,2)) if i==0 else '\n'.join(fs))]+[json.loads((D/'narratives.json').read_text(encoding='utf-8-sig'))[i]])
 docs.append(dict(document_id=did,title=titles[i],source_type=typ,created_at='2026-03-14T20:00:00',author=['Секретарь','Система','Организатор','Илья','Мира','Вера','Аудитор','Архивист','Планировщик'][i],text=text))
 for j,f in enumerate(fs):
  cid=f'C{i*4+j+1:02}';stat='disputed' if i in(3,4) and j<2 else 'reported' if typ=='statement' else 'direct'
  a0=1 if typ=='statement' else 2 if typ=='rule' else 0;a1=2 if stat=='disputed' or cid=='C10' else 1 if stat=='reported' else 0
  claims.append(dict(claim_id=cid,text=f,document_id=did,evidence=f,status=stat,path=[a0,a1,0 if cid=='C28' or i==7 else 2 if i==8 or cid in ('C01','C09','C10','C15','C16','C19','C20','C21','C23','C24','C26','C27') else 1],event_time={'C02':'18:00','C03':'19:00','C04':'18:25','C05':'18:10','C06':'18:20','C07':'18:15','C08':'18:12','C11':'18:22','C12':'18:24','C13':'18:15','C14':'18:15','C17':'18:15','C18':'18:15','C22':'18:24','C25':'18:22','C28':'17:55'}.get(cid,'99:99')))
qs=[('direct','Во сколько зарегистрирован вход Лады?','entailed','В 18:12.',['C08'],[]),('direct','Первую сборку опубликовала служба «Шлюз»?','entailed','Да, в 18:15.',['C07'],[]),('multi_hop','Имела ли Лада право публикации в момент первого выпуска?','contradicted','Нет: выпуск в 18:15, право выдано в 18:20.',['C06','C07'],[]),('multi_hop','Было ли первое задание поставлено в очередь до начала заморозки?','entailed','Да: 17:55 раньше 18:00.',['C28','C02'],[]),('temporal','Первый выпуск произошёл после выдачи Ладе права публикации?','contradicted','Нет: 18:15 раньше 18:20.',['C07','C06'],[]),('temporal','Контрольная сборка опубликована после письменного разрешения?','entailed','Да: 18:25 позже 18:24.',['C04','C12'],[]),('rule_exception','Разрешена ли контрольная публикация по резервному исключению?','entailed','Да: ключ и разрешение получены до 18:25.',['C10','C11','C12','C04'],[]),('rule_exception','Разрешён ли первый выпуск резервным исключением?','contradicted','Нет: ключ включён только в 18:22, позже выпуска.',['C10','C11','C07','C25'],[]),('contradiction','Находилась ли Лада в серверной в 18:15?','both','Илья подтверждает, Мира отрицает; выбрать источник нельзя.',['C13'],['C17']),('contradiction','Был ли индикатор красным в 18:15?','both','Илья говорит о красном, Мира о зелёном.',['C14'],['C18']),('insufficient','Илья намеренно вызвал первый выпуск для срыва турнира?','insufficient',None,['C23'],[]),('insufficient','Архив скачала Лада?','insufficient',None,['C24'],[])]
questions=[dict(question_id=f'Q{i+1:02}',type=t,question=q,gold_status=s,gold_answer=a,gold_evidence_ids=e,gold_counterevidence_ids=c) for i,(t,q,s,a,e,c) in enumerate(qs)]
save('documents.jsonl',docs);save('claims.jsonl',claims);save('questions.jsonl',questions)
words=sum(len(d['text'].split()) for d in docs)
assert 5000<=words<=8000,words
(D/'gold_freeze.json').write_text(json.dumps({'phase':'before any model inference','words':words,'sha256':{f:hashlib.sha256((D/f).read_bytes()).hexdigest() for f in ['documents.jsonl','claims.jsonl','questions.jsonl']}},indent=2),encoding='utf8')
print('words',words)